insert into public.rule_versions (rule_card_id, version, status, risk_level, title, description, risky_examples, match_patterns, safe_replacements, flag_trigger, safe_fix, source_org, source_title, source_url, source_reference, effective_date, last_verified_at, verification_note, legal_review_status) values ('TR-RY-TAKVIYE-BESLENME', 1, 'active', 'high', 'Takviyenin normal beslenmenin yerine geçtiği izlenimi', 'Takviye edici gıdaların reklamı, normal beslenme kapsamında tüketilen gıdaların yerine geçtiği izlenimi uyandıracak şekilde yapılamaz.', array['Öğün yerine bir kapsül', 'Yemek yemeden tüm ihtiyacını karşıla']::text[], array['(ogun|yemek|kahvalti)\w*\s+yerine', '(beslenme\w*|yemeg\w*)\s+(\S+\s+)?yerini\s+(alir|tutar)', '(tum|butun)\s+(\S+\s+)?ihtiyac\w*\s+(\S+\s+)?karsila\w*']::text[], '[{"pattern":"(ogun|yemek|kahvalti)\\w*\\s+yerine","replacement":"dengeli beslenmenizin yanında"}]'::jsonb, null, 'Takviyeyi dengeli beslenmenin yanında kullanılan bir ürün olarak konumlayın; öğün yerine geçtiğini ima etmeyin.', 'T.C. Ticaret Bakanlığı', 'Ticari Reklam ve Haksız Ticari Uygulamalar Yönetmeliğinde değişiklik (RG 01.07.2026, sayı 33297) – Bakanlık duyurusu', 'https://ticaret.gov.tr/haberler/ticaret-bakanligi-tarafindan-ticari-reklam-ve-haksiz-ticari-uygulamalar-yonetmeliginde-yapilan-degisikliklerle-tuketicilerin-aldatici-reklam-ve-ticari-uygulamalara-karsi-korunmasi-guclendiriliyor', 'Ticari Reklam ve Haksız Ticari Uygulamalar Yönetmeliği md. 27/10 (yeni)', '2026-08-01'::date, '2026-11-16'::date, 'Değişikliğin özü Ticaret Bakanlığı''nın 01.07.2026 tarihli resmî duyurusunda okundu. Madde numarası RÖK karşılaştırma tablosundan alındı; Resmî Gazete metni bu ortamdan okunamadı, hukukçu teyidi bekliyor.', 'pending')
  on conflict (rule_card_id, version) do nothing;

