insert into public.rule_versions (rule_card_id, version, status, risk_level, title, description, risky_examples, match_patterns, safe_replacements, flag_trigger, safe_fix, source_org, source_title, source_url, source_reference, effective_date, last_verified_at, verification_note, legal_review_status) values ('TR-RY-TAKVIYE-KARSILASTIRMA', 1, 'active', 'medium', 'Takviyede sağlık beyanı içeren karşılaştırma', 'Takviye edici gıdalarda karşılaştırmalı reklam, sağlık beyanı kapsamına giren hususlar hariç olmak üzere yapılabilir. Sağlık etkisi üzerinden rakiple kıyaslama risklidir.', array['Diğer takviyelerden 3 kat daha etkili', 'Rakiplerinden daha hızlı zayıflatır']::text[], array['(diger|rakip)\w*\s+(\S+\s+){0,3}(daha|kat)\s+(\S+\s+)?(etkili|hizli|guclu|faydali)', '\d+\s*kat\s+daha\s+(etkili|guclu|hizli)']::text[], '[]'::jsonb, null, 'Sağlık etkisi üzerinden kıyaslama yapmayın; karşılaştırma yalnızca fiyat, içerik miktarı gibi doğrulanabilir özelliklere dayanmalı.', 'T.C. Ticaret Bakanlığı', 'Ticari Reklam ve Haksız Ticari Uygulamalar Yönetmeliğinde değişiklik (RG 01.07.2026, sayı 33297) – Bakanlık duyurusu', 'https://ticaret.gov.tr/haberler/ticaret-bakanligi-tarafindan-ticari-reklam-ve-haksiz-ticari-uygulamalar-yonetmeliginde-yapilan-degisikliklerle-tuketicilerin-aldatici-reklam-ve-ticari-uygulamalara-karsi-korunmasi-guclendiriliyor', 'Ticari Reklam ve Haksız Ticari Uygulamalar Yönetmeliği md. 8/3 (değişik)', '2026-08-01'::date, '2026-11-16'::date, 'Değişikliğin özü Ticaret Bakanlığı''nın 01.07.2026 tarihli resmî duyurusunda okundu. Madde numarası RÖK karşılaştırma tablosundan alındı; Resmî Gazete metni bu ortamdan okunamadı, hukukçu teyidi bekliyor. Not: Bakanlık duyurusu sağlık beyanı dışında karşılaştırmaya izin verildiğini söylüyor; ikincil kaynaktaki metin tablosunda yasak ifadesinin sürdüğü görülüyor. Resmî metinle çözülmeli.', 'pending')
  on conflict (rule_card_id, version) do nothing;

insert into public.rule_cards (id, domain, category, sector, platform) values ('TR-6502-USTUNLUK', 'tr_law', 'Kanıtsız üstünlük iddiası', 'genel', 'all')
