insert into public.rule_versions (rule_card_id, version, status, risk_level, title, description, risky_examples, match_patterns, safe_replacements, flag_trigger, safe_fix, source_org, source_title, source_url, source_reference, effective_date, last_verified_at, verification_note, legal_review_status) values ('TR-RY-ACELE-BASKISI', 1, 'requires_review', 'medium', 'Gerçek dışı süre veya stok baskısı', 'Ürünün çok kısa bir süre veya çok sınırlı stokla satılacağını gerçeğe aykırı biçimde belirtmek haksız ticari uygulama sayılabilir.', array['Sadece bugün!', 'Son 3 ürün', 'Son 1 saat, kaçırma']::text[], array['sadece\s+bugun', 'son\s+\d+\s+(urun|adet|kisi)', 'son\s+(\d+\s+)?saat\w*', 'stoklar\w*\s+(\S+\s+)?tukeniyor']::text[], '[]'::jsonb, null, 'Süre ve stok bilgisi gerçekse kampanyanın bitiş tarihini ve stok adedini açıkça yazın; gerçek değilse aciliyet ifadesini kaldırın.', 'T.C. Resmî Gazete', 'Ticari Reklam ve Haksız Ticari Uygulamalar Yönetmeliğinde Değişiklik Yapılmasına Dair Yönetmelik', 'https://www.resmigazete.gov.tr/eskiler/2026/07/20260701-9.htm', 'Yönetmelik eki haksız ticari uygulamalar listesi (madde numarası teyit edilmedi)', null, '2026-11-17'::date, 'Resmî metin bu güncellemede okunmadı; kural yaygın uygulamaya ve ikincil kaynaklara göre yazıldı. Doğrulanana kadar yalnızca bilgilendirme amaçlıdır.', 'pending')
