insert into public.rule_versions (rule_card_id, version, status, risk_level, title, description, risky_examples, match_patterns, safe_replacements, flag_trigger, safe_fix, source_org, source_title, source_url, source_reference, effective_date, last_verified_at, verification_note, legal_review_status) values ('TR-EMLAK-GETIRI', 1, 'requires_review', 'high', 'Kesin değer artışı veya kira getirisi vaadi', 'Konutun değerinin kesin artacağını ya da kira getirisinin garanti olduğunu söylemek aldatıcı reklam riski taşır.', array['Garantili kira getirisi', 'Değeri 2 yılda kesin ikiye katlanır', 'Kesin kazanç']::text[], array['(deger|kira)\w*\s+(\S+\s+){0,2}(garanti|kesin)\w*', 'garantili\s+(kira|getiri|deger)\w*', 'kesin\s+(kazanc|deger artisi|getiri)']::text[], '[]'::jsonb, null, 'Getiri garantisi vermeyin; varsa kira garantisinin sözleşmedeki koşullarını ve süresini açıkça yazın.', 'T.C. Resmî Gazete', 'Ticari Reklam ve Haksız Ticari Uygulamalar Yönetmeliğinde Değişiklik Yapılmasına Dair Yönetmelik', 'https://www.resmigazete.gov.tr/eskiler/2026/07/20260701-9.htm', 'Ticari Reklam Yönetmeliği, aldatıcı reklam (madde numarası teyit edilmedi)', null, '2026-11-17'::date, 'Resmî metin bu güncellemede okunmadı; kural yaygın uygulamaya ve ikincil kaynaklara göre yazıldı. Doğrulanana kadar yalnızca bilgilendirme amaçlıdır.', 'pending')
