insert into public.rule_versions (rule_card_id, version, status, risk_level, title, description, risky_examples, match_patterns, safe_replacements, flag_trigger, safe_fix, source_org, source_title, source_url, source_reference, effective_date, last_verified_at, verification_note, legal_review_status) values ('TT-KILO-YONETIMI', 1, 'requires_review', 'high', 'Kilo verme ürünü veya vaadi', 'TikTok, kilo yönetimi reklamlarını yaş hedeflemesi ve içerik kurallarıyla kısıtlar; bazı kilo verme ürünlerinin reklamı tamamen yasaktır ve olumsuz beden imajı kabul edilmez.', array['Hızlı kilo ver', 'Yağ yakıcı çay', 'Zayıflama hapı']::text[], array['kilo ver\w*', '\bzayifla\w*', 'yag yak\w*', '\bincel\w*']::text[], '[]'::jsonb, null, 'Kilo kaybını vaat etmeyin; ürünü dengeli beslenme ve yaşam tarzının bir parçası olarak anlatın, 18 yaş altını hedeflemeyin.', 'TikTok', 'TikTok reklam politikaları: Kilo yönetimi (Weight Management)', 'https://ads.tiktok.com/help/article/tiktok-ads-policy-weight-management', 'Weight Management (2026 güncellemesi teyit edilmedi)', null, '2026-11-17'::date, 'Platformun resmî politika sayfası bu ortamdan okunamadı; kart yaygın uygulamaya göre yazıldı. Doğrulanana kadar yalnızca bilgilendirme amaçlıdır.', 'pending')
  on conflict (rule_card_id, version) do nothing;

